# Auto-generated by refactor: extracted verbatim from starter.py (factory + blueprints split).
from flask import Blueprint, current_app, jsonify, render_template, request
from flask_login import current_user
from app.auth_middleware import require_auth

from app.config import LB_ALLTIME_KEY, LB_WEEKLY_KEY
from app.extensions import db, redis_client
from app.i18n import t_or
from app.models import DailyQuest, WeeklyWinner
from app.services.gamification import _leaderboard_via_postgres, _leaderboard_via_redis, get_today_progress


bp = Blueprint("gamification", __name__)


@bp.route("/leaderboard")
@require_auth
def leaderboard_page():
    return render_template("leaderboard.html",
        username=current_user.username,
        profile_picture=current_user.avatar_src)


@bp.route("/leaderboard/data")
@require_auth
def leaderboard_data():
    scope = "friends" if request.args.get("scope") == "friends" else "global"
    timeframe = "weekly" if request.args.get("timeframe") == "weekly" else "all_time"

    # Hızlı yol: Redis sorted set'ten anında sırala. Redis yoksa veya herhangi bir
    # hata olursa Postgres ORDER BY yoluna düş (Postgres her zaman kaynaktır).
    if redis_client:
        key = LB_WEEKLY_KEY if timeframe == "weekly" else LB_ALLTIME_KEY
        try:
            return _leaderboard_via_redis(scope, timeframe, key)
        except Exception:
            current_app.logger.warning("Leaderboard Redis yolu başarısız; Postgres'e düşülüyor",
                               exc_info=True)
    return _leaderboard_via_postgres(scope, timeframe)


@bp.route("/leaderboard/reward-check")
@require_auth
def reward_check():
    """Return the newest unseen weekly-reward win for the celebration pop-up."""
    win = (WeeklyWinner.query
           .filter_by(user_id=current_user.id, notified=False)
           .order_by(WeeklyWinner.created_at.desc(), WeeklyWinner.id.desc())
           .first())
    if not win:
        return jsonify({"show": False})
    return jsonify({"show": True, "rank": win.rank,
                    "xp": win.xp_awarded, "week": win.week_key})


@bp.route("/leaderboard/reward-dismiss", methods=["POST"])
@require_auth
def reward_dismiss():
    """Mark the user's pending reward pop-ups as seen so they don't repeat."""
    rows = WeeklyWinner.query.filter_by(user_id=current_user.id, notified=False).all()
    for r in rows:
        r.notified = True
    if rows:
        # Sorgu sırasız: rows[0] keyfi olabilir; birden çok görülmemiş kazançta
        # last_reward_week ESKİ haftaya kayabilirdi (D3). En yeni haftayı al —
        # week_key 'YYYY-Www' leksikografik olarak kronolojik sıralanır.
        current_user.last_reward_week = max(r.week_key for r in rows)
    db.session.commit()
    return jsonify({"ok": True})


@bp.route("/quests")
@require_auth
def quests():
    all_quests = DailyQuest.query.filter_by(is_active=True).all()
    today_progress = get_today_progress(current_user.id)
    progress_map = {p.quest_id: p for p in today_progress}

    quest_data = []
    for q in all_quests:
        prog = progress_map.get(q.id)
        status = "claimed" if prog else "pending"
        # Başlık/açıklama GÖRÜNEN → dile göre; katalogda yoksa kanonik DB metnine düşer.
        quest_data.append({
            "quest": q, "status": status,
            "title": t_or("quest.%s.title" % q.quest_type, q.title),
            "desc": t_or("quest.%s.desc" % q.quest_type, q.description),
        })

    return render_template("quests.html",
        username=current_user.username,
        profile_picture=current_user.avatar_src,
        quest_data=quest_data
    )


